/**
 * Checks of the JSON Schemas generated with `zod2JsonSchemaDefinitions`: they must be valid JSON
 * Schemas and validate the same data as the JSON Schemas generated by Zod with the same
 * definitions without the zod-to-x `override` (which repeat the definitions of copies).
 */
import { z } from "zod/v4";
import Ajv from "ajv";
import Ajv2020 from "ajv/dist/2020";
import addFormats from "ajv-formats";

import { Zod2XConverters } from "../../dist";
import { MIN_ZOD_VERSION_FOR_JSON_SCHEMA_DEFINITIONS } from "../../dist/converters/json_schema_definitions";

export const TARGETS = ["draft-2020-12", "draft-07", "draft-04", "openapi-3.0"] as const;
export type Target = (typeof TARGETS)[number];
export type JsonSchema = Record<string, any>;
export type Params = ReturnType<typeof Zod2XConverters.zod2JsonSchemaDefinitions>;
type ToJsonSchemaParams = NonNullable<Parameters<typeof z.toJSONSchema>[1]>;

const version = (v: string) => v.split(".").map(Number);
const installed = [z.core.version.major, z.core.version.minor, z.core.version.patch];
const minimum = version(MIN_ZOD_VERSION_FOR_JSON_SCHEMA_DEFINITIONS);

/** Whether the installed Zod version supports `zod2JsonSchemaDefinitions`. */
export const isZodSupported =
    (installed.map((part, i) => part - minimum[i]).find((part) => part !== 0) ?? 0) >= 0;

export const zodVersion = installed.join(".");

/** JSON Schema generated with zod-to-x definitions. */
export function toJsonSchema(
    schema: z.ZodType,
    params: ToJsonSchemaParams = {},
    zod2x: Params = Zod2XConverters.zod2JsonSchemaDefinitions()
): JsonSchema {
    return z.toJSONSchema(schema, { ...zod2x, ...params }) as JsonSchema;
}

/** JSON Schema generated by Zod with the same definitions, without the zod-to-x `override`. */
export function toZodJsonSchema(
    schema: z.ZodType,
    params: ToJsonSchemaParams = {},
    zod2x: Params = Zod2XConverters.zod2JsonSchemaDefinitions()
): JsonSchema {
    return z.toJSONSchema(schema, { metadata: zod2x.metadata, ...params }) as JsonSchema;
}

export const definitionsKey = (target: Target = "draft-2020-12") =>
    target === "draft-2020-12" ? "$defs" : "definitions";

export const refTo = (name: string, target: Target = "draft-2020-12") =>
    `#/${definitionsKey(target)}/${name}`;

export function getDefinitions(output: JsonSchema, target: Target = "draft-2020-12"): JsonSchema {
    return output[definitionsKey(target)] ?? {};
}

/**
 * Definition of the root schema. Zod 4.5+ extracts a root with a type name into the definitions
 * and references it, earlier versions keep it inline.
 */
export function getRootDefinition(
    output: JsonSchema,
    target: Target = "draft-2020-12"
): JsonSchema {
    const ref = output.$ref ?? (output.allOf?.length === 1 ? output.allOf[0].$ref : undefined);
    if (typeof ref === "string") {
        return resolvePointer(output, ref);
    }

    const { $schema, $defs, definitions, ...root } = output;
    return root;
}

// ---- traversal of the schemas of a JSON Schema --------------------------------------------------

const SCHEMA_KEYWORDS = new Set([
    "items",
    "additionalItems",
    "additionalProperties",
    "unevaluatedItems",
    "unevaluatedProperties",
    "contains",
    "propertyNames",
    "not",
    "if",
    "then",
    "else",
]);
const SCHEMA_ARRAY_KEYWORDS = new Set(["allOf", "anyOf", "oneOf", "prefixItems"]);
const SCHEMA_MAP_KEYWORDS = new Set([
    "properties",
    "patternProperties",
    "$defs",
    "definitions",
    "dependentSchemas",
]);

/** Calls `visit` for every schema of a JSON Schema (not for the members of keyword maps). */
export function forEachSchema(
    node: unknown,
    visit: (schema: JsonSchema, pointer: string) => void,
    pointer = "#"
) {
    if (typeof node !== "object" || node === null || Array.isArray(node)) {
        return;
    }

    visit(node as JsonSchema, pointer);

    for (const [key, value] of Object.entries(node)) {
        if (SCHEMA_MAP_KEYWORDS.has(key) && typeof value === "object" && value !== null) {
            for (const [member, schema] of Object.entries(value)) {
                forEachSchema(schema, visit, `${pointer}/${key}/${member}`);
            }
        } else if (
            SCHEMA_ARRAY_KEYWORDS.has(key) ||
            (SCHEMA_KEYWORDS.has(key) && Array.isArray(value))
        ) {
            (value as unknown[]).forEach((schema, i) =>
                forEachSchema(schema, visit, `${pointer}/${key}/${i}`)
            );
        } else if (SCHEMA_KEYWORDS.has(key)) {
            forEachSchema(value, visit, `${pointer}/${key}`);
        }
    }
}

export function resolvePointer(root: JsonSchema, ref: string): JsonSchema {
    if (ref === "#") {
        return root;
    }
    if (!ref.startsWith("#/")) {
        throw new Error(`Unsupported reference ${ref}`);
    }

    let current: any = root;
    for (const segment of ref.slice(2).split("/")) {
        const key = decodeURIComponent(segment).replace(/~1/g, "/").replace(/~0/g, "~");
        if (current === null || typeof current !== "object" || !(key in current)) {
            throw new Error(`Unresolved reference ${ref}`);
        }
        current = current[key];
    }
    return current;
}

/** Names of the definitions referenced by a JSON Schema (without following the references). */
export function getReferences(node: unknown, target: Target = "draft-2020-12"): string[] {
    const prefix = `#/${definitionsKey(target)}/`;
    const references = new Set<string>();

    forEachSchema(node, (schema) => {
        if (typeof schema.$ref === "string" && schema.$ref.startsWith(prefix)) {
            references.add(
                decodeURIComponent(schema.$ref.slice(prefix.length))
                    .replace(/~1/g, "/")
                    .replace(/~0/g, "~")
            );
        }
    });

    return [...references].sort();
}

// ---- meaning of a JSON Schema --------------------------------------------------------------------

/** Keywords that do not change the data validated by a schema. */
const ANNOTATIONS = new Set([
    "description",
    "title",
    "examples",
    "deprecated",
    "default",
    "readOnly",
    "writeOnly",
    "$comment",
]);
const IGNORED = new Set(["$schema", "$defs", "definitions", "id", "$id"]);

const sortKeys = (value: any): any =>
    Array.isArray(value)
        ? value.map(sortKeys)
        : value && typeof value === "object"
          ? Object.fromEntries(
                Object.keys(value)
                    .sort()
                    .map((key) => [key, sortKeys(value[key])])
            )
          : value;

const stringify = (value: unknown) => JSON.stringify(sortKeys(value));

/**
 * Keywords that are not independent of other keywords: they can only be merged, or be implied by
 * a referenced schema, together (e.g. `additionalProperties` applies to the properties not
 * declared by the `properties` next to it).
 */
const KEYWORD_GROUPS = [
    ["properties", "patternProperties", "additionalProperties", "unevaluatedProperties"],
    ["items", "prefixItems", "additionalItems", "unevaluatedItems"],
    ["if", "then", "else"],
];
const groupOf = (key: string) => KEYWORD_GROUPS.find((group) => group.includes(key)) ?? [key];

/** Whether the keywords of `implied` hold for any data valid against `schema`. */
function implies(schema: JsonSchema, implied: JsonSchema, keys: string[]): boolean {
    return keys.every((key) => {
        const group = groupOf(key);
        return group.every((member) => stringify(schema[member]) === stringify(implied[member]));
    });
}

interface IMeaning {
    /** Forms of the definitions, by name ("#" for the root). */
    definitions: Map<string, any>;
}

/**
 * Canonical form of what a schema validates. References are kept as the names of the definitions
 * (`$all`), so recursive schemas are not unfolded: two JSON Schemas with the same definitions
 * validate the same data if their roots and definitions have the same forms. The form:
 * - ignores annotations, and the keywords next to `$ref` before draft 2019-09;
 * - merges the members of `allOf` into the schema when their keywords are independent;
 * - replaces references to definitions that are only references (aliases) by what they reference;
 * - removes the keywords that are implied by a referenced definition (same keyword group).
 */
function getMeaning(output: JsonSchema, target: Target): IMeaning {
    const prefix = `#/${definitionsKey(target)}/`;
    const raw = new Map<string, JsonSchema>([
        ["#", output],
        ...Object.entries(getDefinitions(output, target)),
    ]);
    const forms = new Map<string, any>();
    const nameOf = (ref: string) =>
        ref === "#"
            ? "#"
            : ref.startsWith(prefix)
              ? decodeURIComponent(ref.slice(prefix.length)).replace(/~1/g, "/").replace(/~0/g, "~")
              : ref;

    // Form of a schema without expanding aliases or removing implied keywords.
    const shallow = (node: any): any => {
        if (Array.isArray(node)) return node.map(shallow);
        if (node === null || typeof node !== "object") return node;

        const onlyRef = target !== "draft-2020-12" && "$ref" in node;
        const own: JsonSchema = {};
        const refs: string[] = [];
        const members: any[] = [];

        for (const [key, value] of Object.entries<any>(node)) {
            if (IGNORED.has(key) || ANNOTATIONS.has(key)) continue;
            if (key === "$ref") {
                if (!raw.has(nameOf(value))) throw new Error(`Unresolved reference ${value}`);
                refs.push(nameOf(value));
            } else if (onlyRef) {
                continue;
            } else if (key === "allOf") {
                for (const member of value.map(shallow)) {
                    const { $all, $and, ...rest } = member;
                    refs.push(...($all ?? []));
                    members.push(...($and ?? []));
                    if (Object.keys(rest).length > 0) members.push(rest);
                }
            } else if (SCHEMA_MAP_KEYWORDS.has(key)) {
                own[key] = Object.fromEntries(
                    Object.entries<any>(value).map(([name, schema]) => [name, shallow(schema)])
                );
            } else if (SCHEMA_KEYWORDS.has(key) || SCHEMA_ARRAY_KEYWORDS.has(key)) {
                own[key] = shallow(value);
            } else if (key === "required" && Array.isArray(value)) {
                own[key] = [...value].sort();
            } else {
                own[key] = value;
            }
        }

        const unmerged: any[] = [];
        for (const member of members) {
            const keys = Object.keys(member);
            const independent = keys.every((key) =>
                groupOf(key).every(
                    (other) =>
                        !(other in own) ||
                        (other in member && stringify(own[other]) === stringify(member[other]))
                )
            );
            if (independent) Object.assign(own, member);
            else unmerged.push(member);
        }

        return {
            ...own,
            ...(unmerged.length ? { $and: unmerged } : {}),
            ...(refs.length ? { $all: refs } : {}),
        };
    };

    const shallowForms = new Map<string, any>(
        [...raw].map(([name, node]) => [name, shallow(node)])
    );

    const finish = (form: any): any => {
        if (Array.isArray(form)) return form.map(finish);
        if (form === null || typeof form !== "object") return form;

        const { $all, $and, ...own } = form;
        const result: JsonSchema = {};
        for (const [key, value] of Object.entries<any>(own)) {
            result[key] = SCHEMA_MAP_KEYWORDS.has(key)
                ? Object.fromEntries(
                      Object.entries<any>(value).map(([name, schema]) => [name, finish(schema)])
                  )
                : SCHEMA_KEYWORDS.has(key) || SCHEMA_ARRAY_KEYWORDS.has(key)
                  ? finish(value)
                  : value;
        }
        let conjunction: any[] = ($and ?? []).map(finish);
        const refs = [...new Set<string>($all ?? [])].sort();

        // Keywords and conjunction members implied by a referenced definition.
        for (const name of refs.flatMap((ref) => getImplied(ref))) {
            const referenced = finishDefinition(name);
            if (!referenced) continue;
            const { $all: _refs, $and: referencedAnd, ...referencedOwn } = referenced;
            const implied = Object.keys(result).filter(
                (key) => key in referencedOwn && implies(referencedOwn, result, [key])
            );
            implied.forEach((key) => delete result[key]);
            const impliedMembers = new Set(((referencedAnd ?? []) as any[]).map(stringify));
            conjunction = conjunction.filter((member) => !impliedMembers.has(stringify(member)));
        }

        if (conjunction.length)
            result.$and = conjunction
                .map(sortKeys)
                .sort((a, b) => stringify(a).localeCompare(stringify(b)));
        if (refs.length) result.$all = refs;
        return sortKeys(result);
    };

    // Forms of the definitions. A definition being finished (recursive definition) does not imply
    // keywords of the schemas that reference it.
    const inProgress = new Set<string>();
    function finishDefinition(name: string): any {
        if (forms.has(name)) return forms.get(name);
        if (inProgress.has(name) || !shallowForms.has(name)) return undefined;
        inProgress.add(name);
        const form = finish(shallowForms.get(name));
        inProgress.delete(name);
        forms.set(name, form);
        return form;
    }

    // Definitions implied by a reference: the referenced one and the ones it references.
    function getImplied(name: string, stack: string[] = []): string[] {
        if (stack.includes(name)) return [];
        const form = forms.get(name) ?? shallowForms.get(name);
        return [
            name,
            ...((form?.$all ?? []) as string[]).flatMap((ref) => getImplied(ref, [...stack, name])),
        ];
    }

    for (const name of shallowForms.keys()) finishDefinition(name);

    // Aliases (definitions that are only references) stand for what they reference.
    const expand = (name: string, stack: string[] = []): string[] => {
        const { $all, ...own } = forms.get(name) ?? {};
        return $all && Object.keys(own).length === 0 && !stack.includes(name)
            ? $all.flatMap((ref: string) => expand(ref, [...stack, name]))
            : [name];
    };

    // Definitions with the same form validate the same data: they are named by one of them, until
    // no more definitions have the same form.
    const representative = new Map<string, string>();
    const representativeOf = (name: string) => representative.get(name) ?? name;
    const canonical = (form: any): any => {
        if (Array.isArray(form)) return form.map(canonical);
        if (form === null || typeof form !== "object") return form;
        const result: JsonSchema = {};
        for (const [key, value] of Object.entries<any>(form)) {
            result[key] =
                key === "$all"
                    ? [
                          ...new Set<string>(
                              value.flatMap((name: string) => expand(name)).map(representativeOf)
                          ),
                      ].sort()
                    : canonical(value);
        }
        return result;
    };
    // Form of a definition, or of what it references if it is an alias.
    const formOf = (name: string) => {
        const [target] = expand(name);
        const form = canonical(forms.get(expand(name).length === 1 ? target : name));
        const { $all, ...own } = form;
        return $all?.length === 1 && Object.keys(own).length === 0 && $all[0] !== name
            ? canonical(forms.get($all[0]) ?? form)
            : form;
    };

    for (let changed = true, rounds = 0; changed && rounds <= forms.size; rounds++) {
        changed = false;
        const byForm = new Map<string, string>();
        for (const name of [...forms.keys()].filter((name) => name !== "#").sort()) {
            const key = stringify(formOf(name));
            const first = byForm.get(key);
            if (first === undefined) {
                byForm.set(key, representativeOf(name));
            } else if (representativeOf(name) !== representativeOf(first)) {
                representative.set(name, representativeOf(first));
                changed = true;
            }
        }
    }

    // Schemas that have the same form as a definition validate the same data as it: they are
    // replaced by a reference to it (e.g. a definition repeated in place of a reference), until the
    // forms do not change. The definitions themselves and the root are not replaced.
    const intern = (form: any, definitionForms: Map<string, string>, top: boolean): any => {
        if (Array.isArray(form)) return form.map((item) => intern(item, definitionForms, false));
        if (form === null || typeof form !== "object") return form;
        const result: JsonSchema = {};
        for (const [key, value] of Object.entries<any>(form)) {
            result[key] =
                key === "$all"
                    ? value
                    : SCHEMA_MAP_KEYWORDS.has(key)
                      ? Object.fromEntries(
                            Object.entries<any>(value).map(([name, schema]) => [
                                name,
                                intern(schema, definitionForms, false),
                            ])
                        )
                      : SCHEMA_KEYWORDS.has(key) || SCHEMA_ARRAY_KEYWORDS.has(key) || key === "$and"
                        ? intern(value, definitionForms, false)
                        : value;
        }
        const name = top ? undefined : definitionForms.get(stringify(result));
        return name === undefined ? result : { $all: [name] };
    };

    let current = new Map([...forms.keys()].map((name) => [name, formOf(name)]));
    for (let round = 0; round < 8; round++) {
        const definitionForms = new Map<string, string>();
        for (const name of [...current.keys()].filter((name) => name !== "#").sort()) {
            const key = stringify(current.get(name));
            if (!definitionForms.has(key)) definitionForms.set(key, representativeOf(name));
        }
        const next = new Map(
            [...current].map(([name, form]) => [name, intern(form, definitionForms, true)])
        );
        const unchanged = [...next].every(
            ([name, form]) => stringify(form) === stringify(current.get(name))
        );
        current = next;
        if (unchanged) break;
    }

    return { definitions: current };
}

/**
 * Canonical form of what a JSON Schema validates (see `getMeaning`): two JSON Schemas with the
 * same form validate the same data.
 */
export function getValidation(output: JsonSchema, target: Target): string {
    return stringify(Object.fromEntries(getMeaning(output, target).definitions));
}

/**
 * Annotations that apply to each data location (`/property/items...`) up to a data depth, with all
 * the references resolved: the same set means that no annotation is lost or added, whatever the
 * structure of the references.
 */
export function getAnnotations(output: JsonSchema, target: Target, maxDepth = 8): string[] {
    const annotations = new Set<string>();

    const walk = (node: any, location: string, depth: number, stack: string[]) => {
        if (node === null || typeof node !== "object" || Array.isArray(node) || depth > maxDepth) {
            return;
        }
        // References without data depth can only be followed once (e.g. `allOf` of itself).
        if (typeof node.$ref === "string" && !stack.includes(node.$ref)) {
            walk(resolvePointer(output, node.$ref), location, depth, [...stack, node.$ref]);
        }
        if (target !== "draft-2020-12" && "$ref" in node) {
            return;
        }

        const child = (schema: any, childLocation: string) =>
            walk(schema, childLocation, depth + 1, []);
        for (const [key, value] of Object.entries<any>(node)) {
            if (ANNOTATIONS.has(key)) {
                annotations.add(`${location} ${key}=${JSON.stringify(value)}`);
            } else if (key === "properties" || key === "patternProperties") {
                for (const [name, schema] of Object.entries(value))
                    child(schema, `${location}/${name}`);
            } else if (key === "allOf") {
                // Members of a conjunction apply to the same location.
                value.forEach((schema: any) => walk(schema, location, depth, stack));
            } else if (key === "anyOf" || key === "oneOf") {
                // Alternatives are compared together: the order of the members can change.
                value.forEach((schema: any) => child(schema, `${location}/${key}`));
            } else if (SCHEMA_ARRAY_KEYWORDS.has(key) || SCHEMA_KEYWORDS.has(key)) {
                const schemas = Array.isArray(value) ? value : [value];
                schemas.forEach((schema: any, i: number) =>
                    child(schema, `${location}/${key}${Array.isArray(value) ? i : ""}`)
                );
            }
        }
    };

    walk(output, "", 0, []);
    return [...annotations].sort();
}

// ---- intersections -------------------------------------------------------------------------

/**
 * Zod's JSON Schema with the intersections whose members are definitions merged, as
 * `z.intersection` validates them: the properties of all the objects (a property declared by
 * several ones has to satisfy all of them), the required properties of all of them, and the
 * properties they do not declare are rejected only if all of them reject them. Written
 * independently of the zod-to-x override, to check it.
 */
export function withMergedIntersections(output: JsonSchema, target: Target): JsonSchema {
    const copy = structuredClone(output);
    const definitions = getDefinitions(copy, target);
    const prefix = `#/${definitionsKey(target)}/`;
    const PENDING = Symbol("pending");
    const OBJECT_KEYWORDS = [
        "type",
        "properties",
        "required",
        "additionalProperties",
        "propertyNames",
    ];

    const keywordsOf = (node: JsonSchema) =>
        Object.keys(node).filter((key) => !ANNOTATIONS.has(key));
    const definitionOf = (node: any): string | undefined => {
        if (node === null || typeof node !== "object" || keywordsOf(node).join() !== "$ref")
            return undefined;
        if (typeof node.$ref !== "string" || !node.$ref.startsWith(prefix)) return undefined;
        const name = decodeURIComponent(node.$ref.slice(prefix.length))
            .replace(/~1/g, "/")
            .replace(/~0/g, "~");
        return name in definitions && !name.startsWith("__schema") ? name : undefined;
    };
    const objectOf = (node: any, depth = 0): JsonSchema | null | typeof PENDING => {
        if (depth > 32 || node === null || typeof node !== "object" || Array.isArray(node))
            return null;
        const name = definitionOf(node);
        if (name !== undefined) return objectOf(definitions[name], depth + 1);
        const keywords = keywordsOf(node);
        if (keywords.join() === "allOf") {
            return node.allOf.length === 1 ? objectOf(node.allOf[0], depth + 1) : PENDING;
        }
        if (node.type === "object" && keywords.every((key) => OBJECT_KEYWORDS.includes(key))) {
            return Object.fromEntries(keywords.map((key) => [key, node[key]]));
        }
        return null;
    };
    const catchallOf = (object: JsonSchema) =>
        typeof object.additionalProperties === "object" &&
        Object.keys(object.additionalProperties).length > 0
            ? object.additionalProperties
            : undefined;
    const unique = (items: any[]) =>
        items.filter(
            (item, i) => items.findIndex((other) => stringify(other) === stringify(item)) === i
        );

    const merge = (objects: JsonSchema[], depth = 0): JsonSchema => {
        const names = unique(objects.flatMap((object) => Object.keys(object.properties ?? {})));
        const properties: JsonSchema = {};
        for (const name of names) {
            const parts = unique(
                objects
                    .map((object) => object.properties?.[name] ?? catchallOf(object))
                    .filter((part) => part !== undefined)
            );
            const nested = parts.map((part) => objectOf(part, depth + 1));
            properties[name] =
                parts.length === 1
                    ? parts[0]
                    : nested.every((object) => object !== null && object !== PENDING)
                      ? merge(nested as JsonSchema[], depth + 1)
                      : { allOf: parts };
        }

        const result: JsonSchema = { type: "object", properties };
        const required = unique(objects.flatMap((object) => object.required ?? []));
        if (required.length > 0) result.required = required;
        const propertyNames = unique(
            objects.map((object) => object.propertyNames).filter((names) => names)
        );
        if (propertyNames.length > 0) {
            result.propertyNames =
                propertyNames.length === 1 ? propertyNames[0] : { allOf: propertyNames };
        }
        if (objects.every((object) => object.additionalProperties === false)) {
            result.additionalProperties = false;
        } else {
            const constraints = unique(objects.map(catchallOf).filter((constraint) => constraint));
            if (constraints.length > 0) {
                result.additionalProperties =
                    constraints.length === 1 ? constraints[0] : { allOf: constraints };
            }
        }
        return result;
    };

    let changed = true;
    while (changed) {
        changed = false;
        forEachSchema(copy, (node) => {
            const allOf = node.allOf;
            if (
                !Array.isArray(allOf) ||
                allOf.length < 2 ||
                !allOf.some((member) => definitionOf(member))
            ) {
                return;
            }
            const objects = allOf.map((member) => objectOf(member));
            if (objects.some((object) => object === null || object === PENDING)) {
                return;
            }
            const merged = merge(objects as JsonSchema[]);
            const reference = allOf.find(
                (member) =>
                    definitionOf(member) && stringify(objectOf(member)) === stringify(merged)
            );
            node.allOf = [reference ?? merged];
            changed = true;
        });
    }

    return copy;
}

// ---- validity --------------------------------------------------------------------------------

/**
 * Validator of the target with the strict mode of Ajv: the schema must be valid against the
 * meta-schema of its draft, and must not use unknown keywords. Tuples are not required to set
 * their length. Ajv does not include the meta-schemas of draft-04 and OpenAPI 3.0.
 */
export function createValidator(target: Target) {
    if (target !== "draft-2020-12" && target !== "draft-07") {
        return undefined;
    }

    const options = { strict: true, strictTuples: false, allowUnionTypes: true };
    const ajv = target === "draft-2020-12" ? new Ajv2020(options) : new Ajv(options);
    addFormats(ajv);
    return ajv;
}

const validators = new Map<Target, ReturnType<typeof createValidator>>();

export function compile(output: JsonSchema, target: Target) {
    if (!validators.has(target)) {
        validators.set(target, createValidator(target));
    }
    return validators.get(target)?.compile(output);
}

/** Removes the `id` keyword of Zod registries, emitted by Zod before 4.4. */
export function withoutIds(output: JsonSchema): JsonSchema {
    const copy = structuredClone(output);
    forEachSchema(copy, (schema) => {
        if (typeof schema.id === "string") {
            delete schema.id;
        }
    });
    return copy;
}

/** References with other keywords, which are ignored before draft 2019-09. */
function countRefsWithSiblings(output: JsonSchema): number {
    let count = 0;
    forEachSchema(output, (schema) => {
        if (
            "$ref" in schema &&
            Object.keys(schema).some((key) => !IGNORED.has(key) && key !== "$ref")
        ) {
            count++;
        }
    });
    return count;
}

/**
 * Problems of the JSON Schema of a Zod schema generated with zod-to-x definitions. It must be a
 * valid JSON Schema for the target, and validate the same data with the same annotations as the
 * JSON Schema generated by Zod without the zod-to-x `override`, with the intersections whose members
 * are definitions merged (see `withMergedIntersections`).
 */
export function findProblems(
    schema: z.ZodType,
    target: Target,
    params: ToJsonSchemaParams = {},
    zod2x: Params = Zod2XConverters.zod2JsonSchemaDefinitions()
): string[] {
    const problems: string[] = [];
    let output: JsonSchema;
    let expected: JsonSchema;

    try {
        // Zod 4.3 emits the `id` of the definitions without the zod-to-x override.
        expected = withMergedIntersections(
            withoutIds(toZodJsonSchema(schema, { target, ...params }, zod2x)),
            target
        );
    } catch {
        return []; // Not representable by Zod.
    }

    try {
        output = toJsonSchema(schema, { target, ...params }, zod2x);
    } catch (error: any) {
        return [`generation throws: ${error.message}`];
    }

    try {
        compile(output, target);
    } catch (error: any) {
        problems.push(`invalid JSON Schema: ${error.message}`);
    }

    forEachSchema(output, (node, pointer) => {
        if ("id" in node) {
            problems.push(`${pointer} has the "id" keyword`);
        }
        if (typeof node.$ref === "string") {
            try {
                resolvePointer(output, node.$ref);
            } catch (error: any) {
                problems.push(`${pointer}: ${error.message}`);
            }
        }
    });
    if (problems.length > 0) {
        return problems;
    }

    const validation = getValidation(output, target);
    const expectedValidation = getValidation(expected, target);
    if (validation !== expectedValidation) {
        if (process.env.DEBUG_JSON_SCHEMA_CHECKS) {
            const [a, b] = [JSON.parse(validation), JSON.parse(expectedValidation)];
            for (const key of new Set([...Object.keys(a), ...Object.keys(b)])) {
                if (stringify(a[key]) !== stringify(b[key])) {
                    console.log(
                        `${key}\n  output:   ${stringify(a[key])}\n  expected: ${stringify(b[key])}`
                    );
                }
            }
            console.log(JSON.stringify(output), "\n", JSON.stringify(expected));
        }
        problems.push("validates other data than the JSON Schema generated by Zod");
    }

    const annotations = getAnnotations(output, target);
    const expectedAnnotations = getAnnotations(expected, target);
    // A reference to a definition adds its annotations to the ones of the use site (e.g. a new
    // description of a copy): additions are only accepted where the use site sets the keyword.
    const keywordOf = (annotation: string) => annotation.slice(0, annotation.indexOf("="));
    const expectedKeywords = new Set(expectedAnnotations.map(keywordOf));
    const lost = expectedAnnotations.filter((annotation) => !annotations.includes(annotation));
    const added = annotations.filter(
        (annotation) =>
            !expectedAnnotations.includes(annotation) &&
            !expectedKeywords.has(keywordOf(annotation))
    );
    if (lost.length > 0 || added.length > 0) {
        problems.push(`annotations differ: lost ${lost.join(", ")}; added ${added.join(", ")}`);
    }

    if (
        target !== "draft-2020-12" &&
        countRefsWithSiblings(output) > countRefsWithSiblings(expected)
    ) {
        problems.push("references with other keywords, which are ignored by the target");
    }

    return problems;
}

// ---- data ------------------------------------------------------------------------------------

/** Values derived from a valid value: other types, and missing, extra and changed members. */
export function getMutations(value: unknown): unknown[] {
    const mutations: unknown[] = [null, 1, "x", [], {}];

    if (Array.isArray(value)) {
        mutations.push([...value, 7], value.slice(1));
        value.forEach((item, i) =>
            getMutations(item).forEach((mutation) =>
                mutations.push(value.map((other, j) => (j === i ? mutation : other)))
            )
        );
    } else if (value !== null && typeof value === "object") {
        mutations.push({ ...value, unknownKey: 1 });
        for (const key of Object.keys(value)) {
            const { [key]: _removed, ...rest } = value as Record<string, unknown>;
            mutations.push(rest);
            for (const mutation of getMutations((value as any)[key])) {
                mutations.push({ ...value, [key]: mutation });
            }
        }
    } else if (typeof value === "string") {
        mutations.push(`${value}!`, "", value.slice(0, 1), value.repeat(4), 5);
    } else if (typeof value === "number") {
        mutations.push(-1, 0.5, `${value}`, 1e20);
    }

    return mutations;
}
